internal fun requiredLocalImagePromptTransformationMethod(
    containsChinese: Boolean,
    languageCapability: LocalImageTextEncoderLanguageCapability
): LocalImagePromptTransformationMethod = when {
    !containsChinese -> LocalImagePromptTransformationMethod.DIRECT
    languageCapability == LocalImageTextEncoderLanguageCapability.NATIVE_MULTILINGUAL ->
        LocalImagePromptTransformationMethod.NATIVE_MULTILINGUAL
    else -> LocalImagePromptTransformationMethod.OFFLINE_HY_MT2_ZH_TO_EN
}

internal fun offlineImagePromptTranslationRequest(
    prompt: String,
    finalNegativePrompt: String
): OfflinePromptTranslationRequest {
    val promptHasHan = prompt.containsHanScript()
    val negativeHasHan = finalNegativePrompt.containsHanScript()
    require(promptHasHan || negativeHasHan)
    return if (promptHasHan) {
        OfflinePromptTranslationRequest(
            sourceText = prompt,
            negativePrompt = finalNegativePrompt.takeIf { negativeHasHan }.orEmpty()
        )
    } else {
        OfflinePromptTranslationRequest(sourceText = finalNegativePrompt)
    }
}

data class ChatSessionRecord(
    val id: String,
    val title: String,
    val messages: List<ChatMessage>,
    val pinned: Boolean = false,
    val manualTitle: Boolean = false,
    val updatedAt: Long = System.currentTimeMillis(),
    val projectId: String? = null,
    val assistantId: String? = null,
    /** Immutable persona contract captured when this conversation chose an assistant. */
    val assistantSnapshot: AssistantConversationSnapshot? = null,
    /** Historical ownership could not be proved; keep its messages viewable but isolated. */
    val mixedAssistantHistory: Boolean = false,
    val modelMode: String? = null,
    val modelId: String? = null,
    /** Optional per-conversation override. Null inherits the role/global appearance. */
    val appearanceOverride: ChatAppearance? = null,
    val contextSummaries: List<ContextSummaryRecord> = emptyList()
)

internal fun List<ChatSessionRecord>.latestSessionForAssistant(assistantId: String): ChatSessionRecord? =
    asSequence()
        .filter {
            !it.mixedAssistantHistory && it.assistantId == assistantId &&
                it.assistantSnapshot?.assistantId == assistantId
        }
        .maxWithOrNull(compareBy<ChatSessionRecord> { it.updatedAt }.thenBy { it.id })

